"""Portable, offline HTML review report with auditable evidence overlays."""
from __future__ import annotations

import hashlib
import html
import json
import re
from pathlib import Path, PurePosixPath
from urllib.parse import quote

from .evaluation import read_predictions, summarize


def _safe_image_path(run_dir: Path, value: str) -> str | None:
    """Only serve existing image assets inside the run; reject symlink escapes."""
    if "\\" in value or ":" in value:
        return None
    relative = PurePosixPath(value)
    if relative.is_absolute() or ".." in relative.parts or not relative.parts or relative.parts[0] != "assets":
        return None
    if relative.suffix.lower() not in {".png", ".jpg", ".jpeg", ".webp", ".gif"}:
        return None
    path = run_dir.joinpath(*relative.parts)
    try:
        path.resolve().relative_to(run_dir.resolve())
    except ValueError:
        return None
    return quote(relative.as_posix(), safe="/") if path.is_file() else None


def create_report(run_dir: Path) -> Path:
    run_dir = Path(run_dir)
    predictions = read_predictions(run_dir / "predictions.jsonl")
    records = []
    for p in predictions:
        data = p.model_dump(mode="json")
        data["page_images"] = {}
        for page, image in p.page_images.items():
            safe = _safe_image_path(run_dir, image)
            if safe:
                data["page_images"][page] = safe
            else:
                data["warnings"].append(f"Page {page}: image missing or outside allowed run assets.")
        records.append(data)
    payload = {"predictions": records, "summary": summarize(predictions), "run": run_dir.name}
    raw = json.dumps(payload, ensure_ascii=False, allow_nan=False)
    # Safe inside a script element, including malicious strings containing </script>.
    serialized = raw.replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    fingerprint = hashlib.sha256(raw.encode()).hexdigest()[:24]
    values = {"TITLE": html.escape(run_dir.name), "PAYLOAD": serialized, "RUN_KEY": fingerprint}
    output = re.sub(r"__(TITLE|PAYLOAD|RUN_KEY)__", lambda match: values[match.group(1)], _TEMPLATE)
    destination = run_dir / "report.html"
    destination.write_text(output, encoding="utf-8")
    return destination


